"""Прямое поручение: зафиксировать отдельную открытую проблему модуля FlyVis."""
from pathlib import Path
from datetime import datetime
from zoneinfo import ZoneInfo
import hashlib,json,shutil,sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
OUT=ROOT/'runs/flyvis_motion_delay_problem_20261104'

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()

def main():
    OUT.mkdir(exist_ok=False)
    vault=ROOT/'ObsidianFlyVis';shutil.copytree(vault,OUT/'vault_before')
    path=ROOT/'experiments/system_problems.json';shutil.copy2(path,OUT/'system_problems_before.json')
    plan=ROOT/'dissertation/ЕДИНЫЙ_ПЛАН.md';shutil.copy2(plan,OUT/'plan_before.md')
    data=json.loads(path.read_text(encoding='utf-8'));assert not any(x['id']=='С7' for x in data['problems'])
    sources=['runs/flyvis_y1_latency_fp64_20261104/analysis.json','runs/flyvis_y1_latency_fp64_20261104/secondary_summary.json','runs/flyvis_y1_latency_fp64_20261104/independent_audit.json','runs/flyvis_y1_latency_fp64_20261104/protocol.json']
    problem=dict(id='С7',title='Запаздывание реакции FlyVis при развороте движения',status='open',
      component='полный модуль FlyVis: подготовка изображения, ядро с состоянием и штатный считыватель движения',
      fact='При искусственном развороте глобального движения на четырёх реальных изображениях штатный модуль FlyVis в двойной точности устойчиво менял знак выхода на 2,0625 кадра позже DIS — метода оценки оптического потока; 95% парный интервал по четырём исходным изображениям [2,0; 2,1875] кадра. При 30 кадрах/с это около 68,75 мс по шкале видео. Удержание кадра и последний внутренний шаг исключают смешивание соседних кадров и усреднение шагов как полное объяснение. Ослабленный контраст: 3,0625 кадра, описательно.',
      hypotheses=['Рабочая гипотеза: вклад в задержку вносят постоянные времени нейронов и динамика ядра. Конкретная причина не установлена.',
       'Альтернатива: вклад даёт считыватель, преобразование изображения или их взаимодействие с состоянием ядра; проверка не отделяет эти причины.',
       'После остановки остаточный выход может включать смещение считывателя на новом неподвижном изображении; его нельзя целиком приписать памяти движения.'],
      next_check='Согласовать и проверить минимальное изменение временных констант против штатных при одинаковых входах и считывателе; отдельно контролировать влияние шага интегрирования, амплитуду и слабый контраст. До проверки определить формулу, границы, данные и критерий; без подбора по этой серии.',
      closure='Проблема открыта. Для решения нужно показать воспроизводимое уменьшение задержки относительно штатной версии при сопоставимых условиях, без существенного ухудшения ошибок и устойчивости, затем подтвердить пользу на отложенных реальных последовательностях и, если заявляется польза сопровождению, полным трекером. Критерии заранее фиксируются в новом протоколе.',
      evidence=[dict(source=s,sha256=sha(ROOT/s),claim=claim) for s,claim in zip(sources,['Первичный результат и интервал','Все описательные сравнения и цензурированные остановки','Независимая проверка входов, DIS и метрик; CPU/GPU сверены на одной последовательности','Условия, заданные до вычисления'])],
      cards=['flyvis_y1_latency_fp64_v1'],legacy=[],first_seen='2026-11-04',updated='2026-11-04',
      cases=[dict(date='2026-11-04',fact='Диагностическая серия: 64 последовательности, четыре исходных изображения, одна модель flow/0000/000; результаты не являются HOTA или доказательством причины в ядре.',evidence=sources)],
      limitations='Четыре изображения — четыре единицы сводки, не 64 независимых видео; искусственное глобальное движение, не траектории отдельных объектов; одна модель ансамбля; двойная точность; исходная частичная GPU-FP32 серия не принята; абсолютная амплитуда номинальна; это не оценка времени вычисления и не независимый итоговый тест.')
    data['problems'].append(problem)
    temp=path.with_suffix('.motion_delay.next');temp.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');temp.replace(path)
    now=datetime.now(ZoneInfo('Europe/Moscow'));raw=plan.read_bytes();mark='## Журнал изменений'.encode();nl=b'\r\n' if mark+b'\r\n' in raw else b'\n'
    entry=f'\n**{now:%d.%m.%Y, %H:%M} MSK** — По поручению автора запаздывание добавлено в проблемы FlyVis\n\nДобавлена открытая проблема С7 с первичными источниками и SHA в `experiments/system_problems.json`. При развороте средняя разница2,0625кадра [2;2,1875] относительно DIS на четырёх исходных изображениях. Запаздывание измерено, но не устранено; причина в постоянных времени ядра остаётся гипотезой. Условия, вторичные исходы, границы вывода и различающая проверка сохранены; результат не называется HOTA. Ранее существующие проблемы и гипотезы сохраняются.\n\n'
    plan.write_bytes(raw.replace(mark+nl,mark+nl+entry.encode(),1))
    print('Зарегистрирована С7 — открыта; причина и решение пока не доказаны.')

if __name__=='__main__':main()
